import React, { useEffect } from 'react';

function Toast({ message, onClose }) {
  useEffect(() => {
    if (message) {
      const timer = setTimeout(onClose, 3000);
      return () => clearTimeout(timer);
    }
  }, [message, onClose]);

  if (!message) return null;
  return (
    <div className="fixed top-4 right-4 bg-white text-gray-800 px-6 py-3 rounded-lg shadow-lg border-l-4 border-blue-500 max-w-sm z-50 animate-pulse">
      {message}
    </div>
  );
}

export default Toast;
